<script setup lang="ts">
import { computed, shallowRef, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useAuthStore } from '../../stores/auth'
import { fetchRequests, requestStatusNames } from '../../api/repair-request'
import { useBusinessRead } from '../../composables/useBusinessRead'
import { businessReturnTo } from '../../router/businessNavigation'
import RequestForm from './RequestForm.vue'
const route = useRoute(), router = useRouter(), auth = useAuthStore(), keyword = shallowRef(String(route.query.keyword ?? '')), status = shallowRef(String(route.query.status ?? ''))
const returnTo = computed(() => businessReturnTo(route.query.returnTo, '/requests'))
function saved(receipt: { resourceId: string }) { void router.push({ path: `/requests/${receipt.resourceId}`, query: { returnTo: returnTo.value } }) }
const { data, loading, message, stale, lastSuccessAt, clear, load } = useBusinessRead(() => fetchRequests({ page: Math.max(1, Number(route.query.page ?? 1) || 1), pageSize: 20, keyword: String(route.query.keyword ?? ''), status: String(route.query.status ?? '') }))
function apply(page = 1) { void router.replace({ path: route.path, query: { keyword: keyword.value, status: status.value, page: String(page) } }) }
watch(() => route.fullPath, () => { clear(); if (route.path !== '/requests/new') void load() }, { immediate: true })
</script>
<template><section v-if="route.path === '/requests/new'" class="card"><RouterLink :to="returnTo">返回上一页</RouterLink><RequestForm :initial-location-id="typeof route.query.locationId === 'string' ? route.query.locationId : undefined" @saved="saved" /></section><template v-else><div class="page-heading"><div><h1>我的申请</h1><p class="muted">申请审核状态与工单分别管理。退回补充、撤回及重复关闭均保留历史。</p></div><RouterLink v-if="auth.currentUser?.capabilities.canCreateRequest" class="primary link-button" to="/requests/new">新建报修</RouterLink></div><section class="card"><form @submit.prevent="apply()"><div class="form-grid"><label>申请状态<select v-model="status"><option value="">全部状态</option><option v-for="(name, code) in requestStatusNames" :key="code" :value="code">{{ name }}</option></select></label><label>搜索编号／设备名称<input v-model="keyword" maxlength="100"></label></div><div class="actions"><button class="primary" type="submit" :disabled="loading">查询</button><button class="secondary" type="button" :disabled="loading" @click="status = ''; keyword = ''; apply()">重置</button><button class="secondary" type="button" :disabled="loading" @click="load">刷新</button></div></form></section><p v-if="message" class="notice" role="alert">{{ message }} {{ stale ? `保留上次数据，可能过期；上次成功 ${lastSuccessAt}` : '' }} <button class="text-button" @click="load">重试</button></p><p v-if="loading" role="status">正在读取申请…</p><section v-if="data" class="card"><p>符合当前条件 {{ data.total }} 条</p><p v-if="!data.records.length" class="muted">当前没有符合条件的本人申请。</p><div class="review-list"><article v-for="request in data.records" :key="request.id" class="person-row"><div><strong>{{ request.requestNo }} · {{ request.equipmentName }}</strong><p>{{ requestStatusNames[request.status] }} · {{ request.locationNameSnapshot || '未关联3D位置' }}</p><p>首次提交 {{ new Date(request.firstSubmittedAt).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai' }) }}</p><p v-if="request.workOrder">关联工单 {{ request.workOrder.workOrderNo }} · {{ request.workOrder.status === 'PENDING_ACCEPT' ? '待接单' : request.workOrder.status }}</p></div><RouterLink :to="{ path: `/requests/${request.id}`, query: { returnTo: route.fullPath } }">{{ request.status === 'NEEDS_SUPPLEMENT' ? '查看并补充' : '查看申请详情' }}</RouterLink></article></div><div class="actions"><button class="secondary" :disabled="data.page <= 1 || loading" @click="apply(data.page - 1)">上一页</button><span>第{{ data.page }}页</span><button class="secondary" :disabled="data.page * data.pageSize >= data.total || loading" @click="apply(data.page + 1)">下一页</button></div></section></template></template>
